{
  "$schema": "https://opencode.ai/config.json",
  "model": "vllm-docker/qwen-coder",
  "plugins": ["-opencode.provider.vllm"],
  "agents": {
    "title": { "model": "vllm-docker/qwen-coder#none" },
    "compaction": { "model": "vllm-docker/qwen-coder#none" }
  },
  "compaction": { "auto": true, "keep": { "tokens": 12000 }, "buffer": "20%" },
  "providers": {
    "vllm-docker": {
      "name": "vLLM (Docker)",
      "package": "@opencode/ai/providers/openai-compatible",
      "settings": {
        "baseURL": "http://127.0.0.1:8000/v1",
        "apiKey": "{env:VLLM_API_KEY}",
        "headerTimeout": 600000
      },
      "compatibility": { "reasoningField": "reasoning" },
      "models": {
        "qwen-coder": {
          "modelID": "qwen-coder",
          "name": "Qwen (vLLM, thinking toggle)",
          "capabilities": { "tools": true, "input": ["text"], "output": ["text"], "reasoning": { "supported": true } },
          "limit": { "context": 65536, "output": 16384 },
          "variants": [
            { "id": "thinking", "body": { "chat_template_kwargs": { "enable_thinking": true } } },
            { "id": "none", "body": { "chat_template_kwargs": { "enable_thinking": false } } }
          ]
        },
        "gemma": {
          "modelID": "gemma",
          "capabilities": { "tools": true, "input": ["text"], "output": ["text"], "reasoning": { "supported": true } },
          "limit": { "context": 65536, "output": 16384 },
          "variants": [
            { "id": "thinking", "body": { "chat_template_kwargs": { "enable_thinking": true } } },
            { "id": "none", "body": { "chat_template_kwargs": { "enable_thinking": false } } }
          ]
        },
        "nemotron": {
          "modelID": "nemotron",
          "capabilities": { "tools": true, "input": ["text"], "output": ["text"], "reasoning": { "supported": true } },
          "limit": { "context": 131072, "output": 16384 },
          "variants": [
            { "id": "thinking", "body": { "chat_template_kwargs": { "enable_thinking": true } } },
            { "id": "none", "body": { "chat_template_kwargs": { "enable_thinking": false } } }
          ]
        },
        "gpt-oss-20b": {
          "modelID": "gpt-oss-20b",
          "capabilities": { "tools": true, "input": ["text"], "output": ["text"], "reasoning": { "supported": true, "effort": ["low", "medium", "high"] } },
          "limit": { "context": 131072, "output": 16384 }
        },
        "coder-instruct": {
          "modelID": "coder-instruct",
          "capabilities": { "tools": true, "input": ["text"], "output": ["text"], "reasoning": { "supported": false } },
          "limit": { "context": 65536, "output": 16384 }
        }
      }
    }
  }
}

{
  "$schema": "https://opencode.ai/config.json",
  "model": "llamacpp/local",
  "providers": {
    "llamacpp": {
      "name": "llama.cpp server (Docker)",
      "package": "@opencode/ai/providers/openai-compatible",
      "settings": { "baseURL": "http://127.0.0.1:8080/v1", "headerTimeout": 600000 },
      "compatibility": { "reasoningField": "reasoning_content" },
      "models": {
        "local": {
          "modelID": "local",
          "name": "llama-server model",
          "capabilities": { "tools": true, "input": ["text"], "output": ["text"], "reasoning": { "supported": true } },
          "limit": { "context": 65536, "output": 16384 },
          "variants": [
            { "id": "thinking", "body": { "chat_template_kwargs": { "enable_thinking": true } } },
            { "id": "none", "body": { "chat_template_kwargs": { "enable_thinking": false } } }
          ]
        }
      }
    }
  }
}

